problem:
Problem description
- There is a finite set of candidate transportation methods $$\mathcal{M}$$, indexed by $$m \in \mathcal{M}$$.
- The planning horizon is an aggregated single-period horizon $$\mathcal{T}$$.
- Each method $$m$$ has a pollution rate per trip $$p_m$$ and a shipment capacity per trip $$q_m$$.
- Some methods may have method-specific trip limits $$\bar{x}_m$$ due to operational or road restrictions.
- The company must choose exactly $$K$$ transportation methods from the available set.
- The company must decide how many trips to assign to each chosen method.
- The planning goal is to minimize total pollution generated by all trips while satisfying shipment and trip-limit requirements.
- Required business constraints, stated operationally:
  - Exactly $$K$$ methods must be selected.
  - A method can only be used if it is selected.
  - The number of trips assigned to any method must be a nonnegative integer.
  - Any method-specific trip limit must not be exceeded.
  - The total number of trips across all selected methods must not exceed $$U$$.
  - The total transported quantity must be at least the required demand $$D$$.
  - The solution should use the least-polluting feasible combination of methods and trips.
- A solution is represented by:
  - $$y_m$$, a binary variable indicating whether method $$m$$ is selected.
  - $$x_m$$, an integer variable indicating the number of trips assigned to method $$m$$.
  - $$Z$$, the total pollution of the chosen transportation plan.
  - The chosen method set $$\{m \in \mathcal{M} \mid y_m = 1\}$$ and the corresponding trip allocation $$\{x_m\}_{m \in \mathcal{M}}$$.

Input Format
{
  "sets": {
    "methods": {
      "symbol": "$$\\mathcal{M}$$",
      "description": "Finite set of transportation methods, indexed by $$m \\in \\mathcal{M}$$",
      "shape": "size $$M$$"
    },
    "time_horizon": {
      "symbol": "$$\\mathcal{T}$$",
      "description": "Aggregated single-period planning horizon",
      "shape": "single period"
    }
  },
  "parameters": {
    "pollution_per_trip": {
      "symbol": "$$p_m$$",
      "description": "Pollution generated by one trip of method $$m$$",
      "shape": "vector over $$m \\in \\mathcal{M}$$"
    },
    "capacity_per_trip": {
      "symbol": "$$q_m$$",
      "description": "Shipment capacity provided by one trip of method $$m$$",
      "shape": "vector over $$m \\in \\mathcal{M}$$"
    },
    "trip_limit": {
      "symbol": "$$\\bar{x}_m$$",
      "description": "Maximum allowed trips for method $$m$$, if a method-specific limit exists",
      "shape": "vector over $$m \\in \\mathcal{M}$$ with unrestricted methods allowed to be marked as unlimited"
    },
    "selected_method_count": {
      "symbol": "$$K$$",
      "description": "Exact number of methods that must be selected",
      "shape": "scalar"
    },
    "minimum_demand": {
      "symbol": "$$D$$",
      "description": "Minimum total shipment volume that must be transported",
      "shape": "scalar"
    },
    "maximum_total_trips": {
      "symbol": "$$U$$",
      "description": "Upper bound on the total number of trips across all methods",
      "shape": "scalar"
    }
  },
  "decision_variables": {
    "method_selection": {
      "symbol": "$$y_m$$",
      "description": "Binary selection indicator for method $$m$$",
      "shape": "binary vector over $$m \\in \\mathcal{M}$$"
    },
    "trip_allocation": {
      "symbol": "$$x_m$$",
      "description": "Number of trips assigned to method $$m$$",
      "shape": "integer vector over $$m \\in \\mathcal{M}$$"
    }
  }
}

Output Format
{
  "selected_methods": {
    "symbol": "$$y_m$$",
    "description": "Binary vector indicating which methods are selected",
    "shape": "vector over $$m \\in \\mathcal{M}$$"
  },
  "trip_allocation": {
    "symbol": "$$x_m$$",
    "description": "Integer trip counts assigned to each method",
    "shape": "vector over $$m \\in \\mathcal{M}$$"
  },
  "objective_value": {
    "symbol": "$$Z$$",
    "description": "Minimum achievable total pollution",
    "shape": "scalar"
  },
  "summary_metrics": {
    "total_trips": {
      "symbol": "$$T$$",
      "description": "Total number of trips used in the solution",
      "shape": "scalar"
    },
    "total_shipment": {
      "symbol": "$$V$$",
      "description": "Total transported quantity achieved by the solution",
      "shape": "scalar"
    }
  }
}

